function player(name){const p=new Player(name??'c6-'+(++seq),d);p.location={x:.5,y:65,z:2};p.health=mockHealth(20,20);p.exhaustion=mockHealth(0,20);p.hunger=mockHealth(20,20);p.saturation=mockHealth(5,20);online.push(p);return p;}
function stool(color='blue',p=player()){d.getBlock({...pos,y:63}).setType('minecraft:stone');hand(p,NS+':'+color+'_bar_stool',2);const b=placeFurniture(p,pos);p.selectedSlotIndex=1;hand(p,undefined);return {p,b,e:ensureSeat(b)};}
function light(color='colorless',p=player()){d.getBlock({...pos,y:63}).setType('minecraft:stone');hand(p,NS+':string_lights_'+color,2);const b=placeFurniture(p,pos);p.selectedSlotIndex=1;hand(p,undefined);return {p,b};}
function sofa(color='blue',p=player(),at=pos,yaw=0){d.getBlock({x:at.x,y:at.y-1,z:at.z}).setType('minecraft:stone');p.rotation.y=yaw;p.selectedSlotIndex=0;hand(p,NS+':'+color+'_sofa',2);const b=placeFurniture(p,at);p.selectedSlotIndex=1;hand(p,undefined);return {p,b};}
function table(p=player(),at=pos,yaw=0){p.rotation.y=yaw;p.selectedSlotIndex=0;hand(p,NS+':table',2);const b=placeFurniture(p,at);p.selectedSlotIndex=1;hand(p,undefined);return {p,b};}
function barCounter(p=player(),at=pos,yaw=0){p.rotation.y=yaw;p.selectedSlotIndex=0;hand(p,NS+':bar_counter',2);const b=placeFurniture(p,at);p.selectedSlotIndex=1;hand(p,undefined);return {p,b};}
function glasswareHolder(p=player(),at=pos,yaw=0){p.rotation.y=yaw;p.selectedSlotIndex=0;hand(p,NS+':glassware_holder',2);const b=placeFurniture(p,at);p.selectedSlotIndex=1;hand(p,undefined);return {p,b};}
function pendant(style='blue',p=player(),at=pos,yaw=0){p.rotation.y=yaw;p.selectedSlotIndex=0;hand(p,NS+':'+style+'_pendant_lamp',2);const upper=placeFurniture(p,at);const lower=d.getBlock({x:at.x,y:at.y-1,z:at.z});p.selectedSlotIndex=1;hand(p,undefined);return {p,upper,lower};}
function painting(style='mona_lisa',p=player(),at=pos,face='North',yaw=0){p.rotation.y=yaw;p.selectedSlotIndex=0;hand(p,NS+':'+style+'_painting',2);const b=placeFurniture(p,at,{face});p.selectedSlotIndex=1;hand(p,undefined);return {p,b};}
function bottleHolder(p=player(),at=pos,yaw=0){p.rotation.y=yaw;p.selectedSlotIndex=0;hand(p,NS+':holder',2);const b=placeHolder(p,at);p.selectedSlotIndex=1;hand(p,undefined);return {p,b};}
