function circularRack(p=player(),at=pos,yaw=0){p.rotation.y=yaw;p.selectedSlotIndex=0;hand(p,NS+':circular_rack',2);const b=placeCircularRack(p,at);p.selectedSlotIndex=1;hand(p,undefined);return {p,b};}
function barCabinet(kind='bar_cabinet',p=player(),at=pos,yaw=0){p.rotation.y=yaw;p.selectedSlotIndex=0;hand(p,NS+':'+kind,2);const b=placeBarCabinet(p,at,NS+':'+kind);p.selectedSlotIndex=1;hand(p,undefined);return {p,b};}
function cellarCabinet(p=player(),at=pos,yaw=0){p.rotation.y=yaw;p.selectedSlotIndex=0;hand(p,NS+':cellar_cabinet',2);const b=placeCellarCabinet(p,at);p.selectedSlotIndex=1;hand(p,undefined);return {p,b};}
function mob(p,{x=0,y=0,z=8,type='minecraft:zombie',health=100,extent=.3}={}){const h=p.getHeadLocation(),e=d.spawnEntity(type,{x:h.x+x,y:h.y+y-1,z:h.z+z});e.health=mockHealth(health,health);e.box={center:{x:h.x+x,y:h.y+y,z:h.z+z},extent:{x:extent,y:1,z:extent}};return e;}
function equipMob(e,item='minecraft:diamond_sword'){e._held=typeof item==='string'?new ItemStack(item,1):item?.clone();e.equippable={getEquipment:slot=>slot==='Mainhand'?e._held?.clone():undefined,setEquipment:(slot,value)=>{if(slot!=='Mainhand'||e.rejectEquipment)return false;e._held=value?.clone();return true;}};return e;}
function equipPlayer(p,entries={Head:'minecraft:iron_helmet'}){const worn=new Map(Object.entries(entries).map(([slot,item])=>[slot,typeof item==='string'?new ItemStack(item,1):item.clone()]));p._armor=worn;p.equippable={getEquipment:slot=>worn.get(slot)?.clone(),setEquipment:(slot,value)=>{if(p.rejectEquipment)return false;if(value)worn.set(slot,value.clone());else worn.delete(slot);return true;}};return p;}
function click(p,b,face='Up',faceLocation={x:.5,y:.5,z:.5}){const event={player:p,block:b,blockFace:face,faceLocation,isFirstEvent:true,cancel:false};world.beforeEvents.playerInteractWithBlock.emit(event);system.advance();return event;}
function full(p){for(let i=0;i<36;i++)p.inventory.setItem(i,new ItemStack('minecraft:stone',64));}
function redstone(component,block,previousPowerLevel,powerLevel,{firstUpdate=false}={}){const e={block,previousPowerLevel,powerLevel,firstUpdate};component.onRedstoneUpdate(e);system.advance();return e;}
const thrownDrinks=()=>[...d.entities.values()].filter(e=>e.typeId===THROWN_DRINK);
