test('native Holder after-interact takes one bottle once without before event and respects foreign cancellation',()=>{
 const {p,b}=bottleHolder();p.location={x:b.location.x+.5,y:b.location.y+.5,z:b.location.z+.5};p.selectedSlotIndex=0;hand(p,NS+':wine_q5',1);putHolderBottle(p,b);p.selectedSlotIndex=1;hand(p,undefined);
 const component=regs.blocks.get(NS+':holder'),before=world.beforeEvents.playerInteractWithBlock,emit=before.emit.bind(before);let emitted=0;before.emit=(...args)=>{emitted++;return emit(...args);};
 try{component.onPlayerInteract({player:p,block:b});component.onPlayerInteract({player:p,block:b});system.advance();}finally{before.emit=emit;}
 assert.equal(emitted,0);assert.equal(count(p,NS+':wine_q5'),1);assert.equal(HOLDER_TEST.store.load(holderKey(d.id,b.location)),undefined);
 const q=player(),at={x:3,y:64,z:0};q.location={x:at.x+.5,y:at.y+.5,z:at.z+.5};hand(q,NS+':holder',1);const other=placeHolder(q,at);q.selectedSlotIndex=0;hand(q,NS+':champagne_q2',1);putHolderBottle(q,other);q.selectedSlotIndex=1;hand(q,undefined);component.onPlayerInteract({player:q,block:other,cancel:true});system.advance();
 assert.equal(count(q,NS+':champagne_q2'),0);assert.equal(HOLDER_TEST.store.load(holderKey(d.id,other.location)).item,NS+':champagne_q2');
});
