test('Cellar Cabinet recovery returns cabinet plus all exact bottles atomically',()=>{const {p,b}=cellarCabinet();p.selectedSlotIndex=0;for(const [q,id] of[[{x:.9,y:.9,z:0},NS+':wine_q5'],[{x:.5,y:.5,z:0},NS+':sherry_q6'],[{x:.1,y:.1,z:0},NS+':empty_bottle']]){hand(p,id,1);useCellarCabinet(p,b,'North',q);}hand(p,undefined);const before=count(p,NS+':cellar_cabinet');recoverCellarCabinet(p,b);assert(b.isAir);assert.equal(count(p,NS+':cellar_cabinet'),before+1);assert.equal(count(p,NS+':wine_q5'),1);assert.equal(count(p,NS+':sherry_q6'),1);assert.equal(count(p,NS+':empty_bottle'),1);});
