test('Cellar Cabinet tick repair restores stale connection and missing shelf visuals',()=>{const {p,b}=cellarCabinet();p.selectedSlotIndex=0;hand(p,NS+':wine_q3',1);useCellarCabinet(p,b,'North',{x:.5,y:.5,z:0});for(const e of [...d.entities.values()])if(e.typeId===NS+':cellar_cabinet_bottle_visual')e.remove();CELLAR_CABINET_TEST.visuals.clear();b.setPermutation(b.permutation.withState(POSITION,CABINET_POSITION.MIDDLE));assert(syncCellarCabinetConnection(b));syncCellarCabinetVisuals(b);assert.equal(b.permutation.getState(POSITION),CABINET_POSITION.SINGLE);assert.equal([...d.entities.values()].filter(e=>e.typeId===NS+':cellar_cabinet_bottle_visual').length,1);});
test('Cellar Cabinet event route requires front face and wins before ordinary bottle display',()=>{const {p,b}=cellarCabinet();p.selectedSlotIndex=0;hand(p,NS+':wine_q3',1);p.isSneaking=false;const wrong=click(p,b,'South',{x:.5,y:.5,z:1});assert(wrong.cancel);assert.equal(CELLAR_CABINET_TEST.store.load(cellarCabinetKey(d.id,b.location)).slots.every(x=>x===null),true);const ok=click(p,b,'North',{x:.9,y:.9,z:0});assert(ok.cancel);assert.equal(CELLAR_CABINET_TEST.store.load(cellarCabinetKey(d.id,b.location)).slots[0],NS+':wine_q3');assert(d.getBlock({x:b.location.x,y:b.location.y+1,z:b.location.z}).isAir);});
test('native Bar Counter onPlace bridges cardinal facing and immediately repairs source connections',()=>{
 const component=regs.blocks.get(NS+':bar_counter');assert.equal(typeof component?.onPlace,'function');
 const east=d.getBlock({x:4,y:64,z:0});east.setPermutation(BlockPermutation.resolve(NS+':bar_counter',{[TABLE_CARDINAL]:'east',[FACING]:0,[CONNECTION]:SOFA_CONNECTION.SINGLE}));component.onPlace({block:east});assert.equal(east.permutation.getState(FACING),1);
 const a=d.getBlock({x:0,y:64,z:0}),b=d.getBlock({x:1,y:64,z:0});
 a.setPermutation(BlockPermutation.resolve(NS+':bar_counter',{[TABLE_CARDINAL]:'north',[FACING]:0,[CONNECTION]:SOFA_CONNECTION.SINGLE}));component.onPlace({block:a});
 b.setPermutation(BlockPermutation.resolve(NS+':bar_counter',{[TABLE_CARDINAL]:'north',[FACING]:0,[CONNECTION]:SOFA_CONNECTION.SINGLE}));component.onPlace({block:b});
 assert.notEqual(a.permutation.getState(CONNECTION),SOFA_CONNECTION.SINGLE);assert.notEqual(b.permutation.getState(CONNECTION),SOFA_CONNECTION.SINGLE);
});
test('native table onPlace consumes placement_direction state and immediately repairs neighbor connections',()=>{
 const component=regs.blocks.get(NS+':table');assert.equal(typeof component?.onPlace,'function');
 const a=d.getBlock({x:0,y:64,z:0}),b=d.getBlock({x:1,y:64,z:0});
 a.setPermutation(BlockPermutation.resolve(NS+':table',{[TABLE_CARDINAL]:'north',[AXIS]:0,[POSITION]:TABLE_POSITION.SINGLE}));
 component.onPlace({block:a});assert.equal(a.permutation.getState(POSITION),TABLE_POSITION.SINGLE);
 b.setPermutation(BlockPermutation.resolve(NS+':table',{[TABLE_CARDINAL]:'north',[AXIS]:0,[POSITION]:TABLE_POSITION.SINGLE}));
 component.onPlace({block:b});
 assert.notEqual(a.permutation.getState(POSITION),TABLE_POSITION.SINGLE);
 assert.notEqual(b.permutation.getState(POSITION),TABLE_POSITION.SINGLE);
});
test('three source tables form X-axis LEFT/MIDDLE/RIGHT using native persistent direction state',()=>{const p=player(),mid=table(p,{x:0,y:64,z:0},0).b,right=table(p,{x:1,y:64,z:0},0).b,left=table(p,{x:-1,y:64,z:0},0).b;assert.equal(tableAxisFromCardinal(left.permutation.getState(TABLE_CARDINAL)),TABLE_AXIS.X);assert.equal(left.permutation.getState(AXIS),0);assert.equal(left.permutation.getState(POSITION),TABLE_POSITION.LEFT);assert.equal(mid.permutation.getState(POSITION),TABLE_POSITION.MIDDLE);assert.equal(right.permutation.getState(POSITION),TABLE_POSITION.RIGHT);});
test('connected table row rejects perpendicular takeover while a standalone table can form a Z row',()=>{const p=player(),mid=table(p,{x:0,y:64,z:0},0).b;table(p,{x:1,y:64,z:0},0);table(p,{x:-1,y:64,z:0},0);const cross=table(p,{x:0,y:64,z:-1},90).b;assert.equal(tableAxisFromCardinal(mid.permutation.getState(TABLE_CARDINAL)),TABLE_AXIS.X);assert.equal(mid.permutation.getState(POSITION),TABLE_POSITION.MIDDLE);assert.equal(cross.permutation.getState(POSITION),TABLE_POSITION.SINGLE);const q=player('z-row'),a=table(q,{x:4,y:64,z:0},90).b,b=table(q,{x:4,y:64,z:-1},90).b;assert.equal(tableAxisFromCardinal(a.permutation.getState(TABLE_CARDINAL)),TABLE_AXIS.Z);assert.notEqual(a.permutation.getState(POSITION),TABLE_POSITION.SINGLE);assert.equal(tableAxisFromCardinal(b.permutation.getState(TABLE_CARDINAL)),TABLE_AXIS.Z);assert.equal(a.permutation.getState(AXIS),0);assert.equal(b.permutation.getState(AXIS),0);});
test('removing middle table reconnects both remaining ends to SINGLE and returns exactly one table',()=>{const p=player(),mid=table(p,{x:0,y:64,z:0},0).b,right=table(p,{x:1,y:64,z:0},0).b,left=table(p,{x:-1,y:64,z:0},0).b;const before=count(p,NS+':table');recoverFurniture(p,mid);assert(mid.isAir);assert.equal(left.permutation.getState(POSITION),TABLE_POSITION.SINGLE);assert.equal(right.permutation.getState(POSITION),TABLE_POSITION.SINGLE);assert.equal(count(p,NS+':table'),before+1);});
test('table tick migrates legacy non-default axis state onto native cardinal direction',()=>{const {b}=table();b.setPermutation(b.permutation.withState(AXIS,TABLE_AXIS.Z).withState(TABLE_CARDINAL,'north').withState(POSITION,TABLE_POSITION.LEFT));assert(syncTable(b));assert.equal(b.permutation.getState(AXIS),0);assert.equal(tableAxisFromCardinal(b.permutation.getState(TABLE_CARDINAL)),TABLE_AXIS.Z);assert.equal(b.permutation.getState(POSITION),TABLE_POSITION.SINGLE);});
test('table 20-tick repair collapses stale connected state without a neighbor',()=>{const {b}=table();b.setPermutation(b.permutation.withState(TABLE_CARDINAL,'north').withState(AXIS,0).withState(POSITION,TABLE_POSITION.MIDDLE));assert(syncTable(b));assert.equal(b.permutation.getState(POSITION),TABLE_POSITION.SINGLE);assert.equal(b.permutation.getState(AXIS),0);});
