test('native stool after-interact seats once without before event and ignores foreign cancellation',()=>{
 const {p,b,e}=stool();p.location={x:b.location.x+.5,y:b.location.y+.5,z:b.location.z+.5};const component=regs.blocks.get(NS+':stool'),before=world.beforeEvents.playerInteractWithBlock,emit=before.emit.bind(before);let emitted=0;before.emit=(...args)=>{emitted++;return emit(...args);};
 try{component.onPlayerInteract({player:p,block:b});component.onPlayerInteract({player:p,block:b});system.advance();}finally{before.emit=emit;}
 assert.equal(emitted,0);assert.equal(p.ridingOn,e);assert.deepEqual(e.rideable.getRiders(),[p]);
 const q=player(),at={x:3,y:64,z:0};d.getBlock({x:at.x,y:at.y-1,z:at.z}).setType('minecraft:stone');hand(q,NS+':blue_bar_stool',1);const other=placeFurniture(q,at),otherSeat=ensureSeat(other);q.location={x:other.location.x+.5,y:other.location.y+.5,z:other.location.z+.5};q.selectedSlotIndex=1;hand(q,undefined);component.onPlayerInteract({player:q,block:other,cancel:true});system.advance();assert.equal(q.ridingOn,undefined);assert.equal(otherSeat.rideable.getRiders().length,0);
});
