test('Nether Special Tomb Raider disarms eligible mob, wears item to1 durability and enforces40tick pickup delay',()=>{const p=player(),target=equipMob(mob(p,{type:'minecraft:pillager',z:3}));target._held.nameTag='source weapon';assert(applyCustomEffect(p,{effect:NS+':tomb_raider',duration:90,amplifier:0}));const before=system.currentTick;assert(handleTombRaider({hurtEntity:target,damageSource:{damagingEntity:p}},()=>.299));assert.equal(target._held,undefined);const drop=[...d.entities.values()].find(e=>e.typeId==='minecraft:item');assert(drop);const stack=drop.getComponent('minecraft:item').itemStack,dur=stack.getComponent('minecraft:durability');assert.equal(stack.typeId,'minecraft:diamond_sword');assert.equal(stack.nameTag,'source weapon');assert.equal(dur.damage,dur.maxDurability-1);assert.equal(drop.getDynamicProperty(TOMB_PICKUP_UNLOCK),before+40);let ev={entity:p,item:drop,cancel:false};world.beforeEvents.entityItemPickup.emit(ev);assert(ev.cancel);system.advance(39);ev={entity:p,item:drop,cancel:false};world.beforeEvents.entityItemPickup.emit(ev);assert(ev.cancel);system.advance(1);ev={entity:p,item:drop,cancel:false};world.beforeEvents.entityItemPickup.emit(ev);assert.equal(ev.cancel,false);});
