test('Ardent Heat item-spawn failure restores the source block and does not charge collision costs',()=>{const p=player();assert(applyCustomEffect(p,{effect:NS+':ardent_heat',duration:300,amplifier:0}));p.isSprinting=true;const b=d.getBlock({x:0,y:65,z:3});b.setType('minecraft:end_stone');d.failSpawnItem=true;assert.equal(pulseArdentHeat(p,()=>0),0);assert.equal(b.typeId,'minecraft:end_stone');assert.equal(p.exhaustion.currentValue,0);assert.equal(p.getDynamicProperty(ARDENT_COLLISION_COUNT),undefined);assert.equal([...d.entities.values()].filter(e=>e.typeId==='minecraft:item').length,0);});
